insert into public.brand_sections (client_id,section,content) values ('97902ff1-3440-ccb2-4443-76333c5cc517','overview','{"name":"Harbor & Pine","tagline":"Made for what comes next.","description":"Harbor & Pine creates considered experiences with a clear point of view.","audience":"Curious people who value purposeful design.","tone":["Clear","Confident","Human"],"rules":["Keep the message direct.","Use generous whitespace.","Build on the core brand palette."]}');
insert into public.brand_sections (client_id,section,content) values ('97902ff1-3440-ccb2-4443-76333c5cc517','logos','{"guidance":"Maintain clear space equal to the height of the wordmark.","variants":["Primary wordmark","Compact mark","Reversed wordmark"]}');
insert into public.brand_sections (client_id,section,content) values ('97902ff1-3440-ccb2-4443-76333c5cc517','colors','{"palette":[{"name":"Ink","hex":"#191919"},{"name":"Paper","hex":"#F7F6F2"},{"name":"Stone","hex":"#C9C5BB"},{"name":"Accent","hex":"#D4DCB4"}]}');
