insert into public.brand_sections (client_id,section,content) values ('c8c131b0-5ccd-6495-851f-11baa70b4acd','overview','{"name":"Northfield Bank","tagline":"Made for what comes next.","description":"Northfield Bank creates considered experiences with a clear point of view.","audience":"Curious people who value purposeful design.","tone":["Clear","Confident","Human"],"rules":["Keep the message direct.","Use generous whitespace.","Build on the core brand palette."]}');
insert into public.brand_sections (client_id,section,content) values ('c8c131b0-5ccd-6495-851f-11baa70b4acd','logos','{"guidance":"Maintain clear space equal to the height of the wordmark.","variants":["Primary wordmark","Compact mark","Reversed wordmark"]}');
insert into public.brand_sections (client_id,section,content) values ('c8c131b0-5ccd-6495-851f-11baa70b4acd','colors','{"palette":[{"name":"Ink","hex":"#191919"},{"name":"Paper","hex":"#F7F6F2"},{"name":"Stone","hex":"#C9C5BB"},{"name":"Accent","hex":"#D4DCB4"}]}');
insert into public.brand_sections (client_id,section,content) values ('c8c131b0-5ccd-6495-851f-11baa70b4acd','typography','{"heading":"Inter","body":"Inter","headingSource":"https://rsms.me/inter/","bodySource":"https://rsms.me/inter/","scale":[12,14,16,24,36,56]}');
insert into public.brand_sections (client_id,section,content) values ('c8c131b0-5ccd-6495-851f-11baa70b4acd','visual-style','{"principles":["Natural light","Quiet composition","Honest materials"],"photography":"Focus on authentic moments and simple backgrounds.","use":["Natural light and honest materials.","Keep the hero subject clear."],"avoid":["Heavy filters and busy backgrounds.","Unsupported product claims."]}');
insert into public.brand_sections (client_id,section,content) values ('c8c131b0-5ccd-6495-851f-11baa70b4acd','products','{"items":[{"name":"Essential collection","description":"Our signature everyday offering.","specs":"Core range. Matte finish. Main label must remain legible.","rules":"Use the primary palette and show the complete product."},{"name":"Signature collection","description":"A considered expression for the seasonal campaign.","specs":"Premium range. Warm neutral treatment. Front-facing hero view.","rules":"Keep props minimal and avoid unsupported product claims."},{"name":"Travel collection","description":"A compact offering for moments on the move.","specs":"Compact format. Clear proportions. Include one scale reference.","rules":"Preserve the approved mark and use an uncluttered background."}]}');
insert into public.brand_sections (client_id,section,content) values ('c8c131b0-5ccd-6495-851f-11baa70b4acd','messaging','{"headline":"Every detail, considered.","description":"A clear expression of what matters.","cta":"Discover the collection","terminology":["Collection","Considered design","Everyday essentials"],"rules":["Use plain, specific language.","Avoid urgency that the offer does not support."]}');
insert into public.brand_sections (client_id,section,content) values ('c8c131b0-5ccd-6495-851f-11baa70b4acd','ai','{"instructions":"Write in the Northfield Bank voice: clear, confident and human. Keep sentences concise. Never invent product claims.","use":["Approved client context and confirmed product facts.","Concise English copy."],"never":["Invent certifications or performance claims.","Name the internal designer or expose production notes."]}');
