insert into public.brand_sections (client_id,section,content) values ('87010e42-ec39-7ebd-cf86-308803fa2790','overview','{"name":"Otto & Sons","tagline":"Made for what comes next.","description":"Otto & Sons creates considered experiences with a clear point of view.","audience":"Curious people who value purposeful design.","tone":["Clear","Confident","Human"],"rules":["Keep the message direct.","Use generous whitespace.","Build on the core brand palette."]}');
