insert into public.brand_sections (client_id,section,content) values ('87010e42-ec39-7ebd-cf86-308803fa2790','visual-style','{"principles":["Natural light","Quiet composition","Honest materials"],"photography":"Focus on authentic moments and simple backgrounds.","use":["Natural light and honest materials.","Keep the hero subject clear."],"avoid":["Heavy filters and busy backgrounds.","Unsupported product claims."]}');
insert into public.brand_sections (client_id,section,content) values ('87010e42-ec39-7ebd-cf86-308803fa2790','products','{"items":[{"name":"Essential collection","description":"Our signature everyday offering.","specs":"Core range. Matte finish. Main label must remain legible.","rules":"Use the primary palette and show the complete product."},{"name":"Signature collection","description":"A considered expression for the seasonal campaign.","specs":"Premium range. Warm neutral treatment. Front-facing hero view.","rules":"Keep props minimal and avoid unsupported product claims."},{"name":"Travel collection","description":"A compact offering for moments on the move.","specs":"Compact format. Clear proportions. Include one scale reference.","rules":"Preserve the approved mark and use an uncluttered background."}]}');
insert into public.brand_sections (client_id,section,content) values ('87010e42-ec39-7ebd-cf86-308803fa2790','messaging','{"headline":"Every detail, considered.","description":"A clear expression of what matters.","cta":"Discover the collection","terminology":["Collection","Considered design","Everyday essentials"],"rules":["Use plain, specific language.","Avoid urgency that the offer does not support."]}');
insert into public.brand_sections (client_id,section,content) values ('87010e42-ec39-7ebd-cf86-308803fa2790','ai','{"instructions":"Write in the Otto & Sons voice: clear, confident and human. Keep sentences concise. Never invent product claims.","use":["Approved client context and confirmed product facts.","Concise English copy."],"never":["Invent certifications or performance claims.","Name the internal designer or expose production notes."]}');
