insert into public.brand_sections (client_id,section,content) values ('10a69063-0151-b8c8-9584-2bfef7fe5f43','overview','{"name":"Vela Skincare","tagline":"Made for what comes next.","description":"Vela Skincare creates considered experiences with a clear point of view.","audience":"Curious people who value purposeful design.","tone":["Clear","Confident","Human"],"rules":["Keep the message direct.","Use generous whitespace.","Build on the core brand palette."]}');
