insert into public.brand_sections (client_id,section,content) values ('10a69063-0151-b8c8-9584-2bfef7fe5f43','typography','{"heading":"Inter","body":"Inter","headingSource":"https://rsms.me/inter/","bodySource":"https://rsms.me/inter/","scale":[12,14,16,24,36,56]}');
insert into public.brand_sections (client_id,section,content) values ('10a69063-0151-b8c8-9584-2bfef7fe5f43','visual-style','{"principles":["Natural light","Quiet composition","Honest materials"],"photography":"Focus on authentic moments and simple backgrounds.","use":["Natural light and honest materials.","Keep the hero subject clear."],"avoid":["Heavy filters and busy backgrounds.","Unsupported product claims."]}');
insert into public.brand_sections (client_id,section,content) values ('10a69063-0151-b8c8-9584-2bfef7fe5f43','products','{"items":[{"name":"Essential collection","description":"Our signature everyday offering.","specs":"Core range. Matte finish. Main label must remain legible.","rules":"Use the primary palette and show the complete product."},{"name":"Signature collection","description":"A considered expression for the seasonal campaign.","specs":"Premium range. Warm neutral treatment. Front-facing hero view.","rules":"Keep props minimal and avoid unsupported product claims."},{"name":"Travel collection","description":"A compact offering for moments on the move.","specs":"Compact format. Clear proportions. Include one scale reference.","rules":"Preserve the approved mark and use an uncluttered background."}]}');
insert into public.brand_sections (client_id,section,content) values ('10a69063-0151-b8c8-9584-2bfef7fe5f43','messaging','{"headline":"Every detail, considered.","description":"A clear expression of what matters.","cta":"Discover the collection","terminology":["Collection","Considered design","Everyday essentials"],"rules":["Use plain, specific language.","Avoid urgency that the offer does not support."]}');
insert into public.brand_sections (client_id,section,content) values ('10a69063-0151-b8c8-9584-2bfef7fe5f43','ai','{"instructions":"Write in the Vela Skincare voice: clear, confident and human. Keep sentences concise. Never invent product claims.","use":["Approved client context and confirmed product facts.","Concise English copy."],"never":["Invent certifications or performance claims.","Name the internal designer or expose production notes."]}');
